void* operator new(std::size_t size); 
void operator delete(void* ptr) noexcept;
// For class-specific operators:
ReturnType* ClassName::operator new(std::size_t size);
void ClassName::operator delete(void* ptr) noexcept;

code_example:
#include <iostream>
#include <cstdlib>

class MyClass {
public:
    // Custom global new operator
    static void* operator new(std::size_t size) {
        std::cout << "Custom new for MyClass, size: " << size << "\n";
        void* ptr = std::malloc(size);
        if (!ptr) throw std::bad_alloc();
        return ptr;
    }
    // Custom global delete operator
    static void operator delete(void* ptr) noexcept {
        std::cout << "Custom delete for MyClass\n";
        std::free(ptr);
    }
    void display() const {
        std::cout << "MyClass instance at " << this << "\n";
    }
};

int main() {
    MyClass* obj = new MyClass();
    obj->display();
    delete obj;
    return 0;
}
